export default function DataViewer(props){
    const {input,config,setConfig,setOutput} = props

    // DataViewer only inspects top 10 datapoints
    useEffect(() => {
        if(!input) return;
        let step = 0
        let interval;
        try{
            if (!input?.log && input?.finished =="true" && config?.run && !interval){
                interval = setInterval( () => {
                    setOutput({output:step});
                    step = step > input?.max_steps ? 0 : step+1
                }, input?.interval || 1000)
            }else{
                parseInt(input?.logs) &&
                setOutput({output:input.logs})
            }
        }catch(e){
            console.log(e)
        }
        return (()=>{
                    clearInterval(interval);
                })
    }, [input, config?.run]);

    if (input && input.logs){
        if (typeof input.logs === 'object' && Object.keys(input).length > 0){
